          <MeshGradient maxPixelCount={1250000} className={dark ? "art:absolute art:inset-x-[-8%] art:top-[-12%] art:h-[124%] art:w-[116%] art:transition-opacity art:duration-500 art:opacity-95" : "art:absolute art:inset-x-[-8%] art:top-[-12%] art:h-[124%] art:w-[116%] art:transition-opacity art:duration-500 art:opacity-75"} colors={dark ? ["#08090c", "#0b2455", "#087c82", "#ef5a71", "#f0c3a8"] : ["#f7f1e8", "#7fcfc9", "#5b8fe8", "#f28da1", "#f2cba7"]} speed={reduce ? 0 : 0.24} distortion={1.25} swirl={0.72} grainMixer={0.16} grainOverlay={0.08} scale={1.18}/>
          <div className={dark ? "art:absolute art:inset-0 art:transition-colors art:duration-500 art:bg-gradient-to-b art:from-[#08090c]/72 art:via-[#08090c]/22 art:to-[#08090c]/5" : "art:absolute art:inset-0 art:transition-colors art:duration-500 art:bg-gradient-to-b art:from-[#f7f1e8]/68 art:via-[#f7f1e8]/18 art:to-transparent"}/>
          <div className={dark ? "art:absolute art:inset-0 art:bg-[radial-gradient(circle_at_center,transparent_28%,rgba(0,0,0,0.32)_100%)]" : "art:absolute art:inset-0 art:bg-[radial-gradient(circle_at_center,transparent_34%,rgba(35,25,15,0.08)_100%)]"}/>
        </div>
        <div className="art:relative art:z-10 art:mx-auto art:flex art:min-h-[760px] art:w-full art:max-w-7xl art:flex-col art:px-5 art:@min-[640px]/artemis:px-8 art:@min-[1024px]/artemis:px-10">
          <header className="art:flex art:h-20 art:items-center art:justify-between art:@min-[640px]/artemis:h-24">
            <a href={nav.brand.href} className="art:flex art:min-h-10 art:items-center art:gap-2.5 art:rounded-full art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-current">
              <span className="art:relative art:grid art:size-7 art:place-items-center" aria-hidden="true">
                <span className="art:absolute art:h-7 art:w-3 art:rounded-full art:border art:border-current"/>
