              </ArtemisSharedLayoutBg>
            </nav>
            <div className="art:flex art:items-center">
              {nav.login ? <motion.a {...press} className={dark ? "art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:hover:text-foreground art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:hidden art:@min-[640px]/artemis:inline-flex art:bg-white/8 art:text-white art:hover:bg-white/14 art:h-9 art:rounded-full" : "art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:hover:text-foreground art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:hidden art:@min-[640px]/artemis:inline-flex art:bg-white/60 art:text-black art:hover:bg-white/82 art:h-9 art:rounded-full"} href={nav.login.href} tabIndex={0}>
